// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ERC20SuccessMock token;

    function setUp() public {
        c = new C();
        token = new ERC20SuccessMock();
    }

    function testFuzz_property(address from, address[] memory tos, uint v) public {
        vm.assume(tos.length > 0);
        vm.assume(from != address(0));
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
        }
        bool success = c.transfer(from, address(token), tos, v);
        assertTrue(success);
    }
}

contract ERC20SuccessMock {
    fallback() external payable {}
}
